import time
import random

def mock_api_call(url: str) -> str:
    if random.random() < 0.5:
        raise ConnectionError("模拟网络错误")
    return f"成功响应来自 {url}"

def call_api_with_retry(url: str, max_retries: int = 3) -> str:
    for attempt in range(max_retries):
        try:
            return mock_api_call(url)
        except ConnectionError as e:
            if attempt == max_retries - 1:
                raise RuntimeError(f"所有重试失败: {e}")
            wait = 2 ** attempt
            time.sleep(wait)
    # 不会执行到这里
    raise RuntimeError("未知错误")

