steps.solutionCode:
import time
import random
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

global_cache = {}

def mock_api_call(url: str) -> str:
    if random.random() < 0.5:
        raise ConnectionError("模拟网络错误")
    return f"成功响应来自 {url}"

def call_api_with_fallback(url: str, cache: dict, default: str = "默认响应") -> str:
    logger = logging.getLogger(__name__)
    max_retries = 3
    for attempt in range(max_retries):
        logger.info(f"尝试第 {attempt+1} 次调用 {url}")
        try:
            result = mock_api_call(url)
            cache[url] = result
            return result
        except ConnectionError as e:
            logger.warning(f"调用失败: {e}")
            if attempt < max_retries - 1:
                time.sleep(0.1)
    if url in cache:
        logger.info(f"使用缓存: {cache[url]}")
        return cache[url]
    logger.error(f"所有重试失败，返回默认值")
    return default
